svg.script:
//
  // First visit: install sw.js, which then serves the actual app (with the
  // cross-origin isolation headers threads need) at this same URL.
  (function () {
    var msg = document.getElementById("msg");
    function fail(text) { msg.textContent = text; }
    if (!("serviceWorker" in navigator)) {
      fail("This browser can't run Webleste here (service workers are unavailable, e.g. in private browsing).");
      return;
    }
    var tries = +(sessionStorage.getItem("webleste-reloads") || 0);
    if (tries >= 3) {
      sessionStorage.removeItem("webleste-reloads");
      fail("Webleste failed to start. Reload the page to try again.");
      return;
    }
    navigator.serviceWorker.register("./sw.js")
      .then(function () { return navigator.serviceWorker.ready; })
      .then(function () {
        sessionStorage.setItem("webleste-reloads", tries + 1);
        location.reload();
      })
      .catch(function (e) { fail("Service worker failed: " + e); });
  })();
//
